<?php
require_once __DIR__ . '/../config/auth.php'; exigirPerfil(['Cliente']); require_once __DIR__ . '/../config/conexao.php';
$erro='';$titulo='';$descricao='';$prioridade='Média';$tipoEquip='';$marca='';$modelo='';$numeroSerie='';$estadoFisico='';$acessorios='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$titulo=trim($_POST['titulo']??'');$descricao=trim($_POST['descricao']??'');$prioridade=$_POST['prioridade']??'Média';$tipoEquip=trim($_POST['tipo_equipamento']??'');$marca=trim($_POST['marca']??'');$modelo=trim($_POST['modelo']??'');$numeroSerie=trim($_POST['numero_serie']??'');$estadoFisico=trim($_POST['estado_fisico']??'');$acessorios=trim($_POST['acessorios']??'');
if($titulo===''||$descricao==='')$erro='Preencha o título e a descrição do problema.';
elseif(!in_array($prioridade,['Baixa','Média','Alta'],true))$erro='Selecione uma prioridade válida.';
else{$uid=(int)$_SESSION['usuario_id'];$st=$conn->prepare("INSERT INTO chamados_cliente(usuario_id,titulo,descricao,prioridade,status,tipo_equipamento,marca,modelo,numero_serie,estado_fisico,acessorios) VALUES(?,?,?,?,'Aberto',?,?,?,?,?,?)");$st->bind_param('isssssssss',$uid,$titulo,$descricao,$prioridade,$tipoEquip,$marca,$modelo,$numeroSerie,$estadoFisico,$acessorios);if($st->execute()){header('Location: index.php?criado=1');exit;}else $erro='Não foi possível registrar o chamado. Tente novamente.';}
}
?>
