mensagens de erro, quedas ou contato com líquido..."><?=h($descricao)?></textarea></div><div class="field"><label for="prioridade">Prioridade</label><select id="prioridade" name="prioridade"><option <?= $prioridade==='Baixa'?'selected':''?>>Baixa</option><option <?= $prioridade==='Média'?'selected':''?>>Média</option><option <?= $prioridade==='Alta'?'selected':''?>>Alta</option></select></div></div><div class="form-actions"><button type="submit">Enviar chamado</button><a class="button secondary" href="index.php">Cancelar</a></div></form></section></main></body></html>
